import { witnessesAt } from './pedestrians.js';

const DISPATCH_NAMES = [
  'U12 "PERALTA"', 'U14 "GARCIA"', 'U16 "RODRIGUEZ"', 'U18 "MORENO"',
  'U20 "SILVA"', 'U22 "CASTRO"', 'U24 "ORTIZ"', 'U26 "RUIZ"',
  'U28 "MENDOZA"', 'U30 "FLORES"'
];

const CRIME_POINTS = {
  carjack: 10,
  pedHit: 15,
  mug: 15,
  gunshot: 5,
  copKill: 40,
  policeCarSteal: 40
